import std.io

pub type AppError = Failed(String)

fn pick(s: String) -> String {
    var r: String = s
    if s == "mirror" {
        r = "mirror-x"
    }
    r = r + "!"
    return r
}

pub fn main() effect io -> Result<(), AppError> {
    io.println(pick("mirror"))
    io.println(pick("plain"))
    var acc: String = "a"
    acc = acc + "b"
    acc = acc + "c"
    io.println(acc)
    return Ok(())
}
